import { useEffect, useState } from "react";

function MarksReport() {
  const [students, setStudents] = useState([]);
  const [marks, setMarks] = useState({});
  const [subjects, setSubjects] = useState([]);

  useEffect(() => {
    const studentsList = JSON.parse(localStorage.getItem("students")) || [];
    const marksData = JSON.parse(localStorage.getItem("marks")) || {};
    setStudents(studentsList);
    setMarks(marksData);

    // Get all subjects dynamically
    let allSubjects = new Set();
    Object.values(marksData).forEach(studentMarks => {
      Object.keys(studentMarks).forEach(subj => allSubjects.add(subj));
    });
    setSubjects([...allSubjects]);
  }, []);

  return (
    <div style={{ padding: "20px" }}>
      <h2>Student Report Card</h2>

      {students.length === 0 ? (
        <p>No students found</p>
      ) : (
        <table border="1" cellPadding="8" style={{ borderCollapse: "collapse", width: "100%" }}>
          <thead>
            <tr style={{ background: "#f0f0f0" }}>
              <th>Student Name</th>
              <th>Roll</th>
              {subjects.map(subj => (
                <th key={subj}>{subj}</th>
              ))}
              <th>Total</th>
              <th>Percentage</th>
            </tr>
          </thead>
          <tbody>
            {students.map(student => {
              const studentMarks = marks[student.id] || {};
              const total = subjects.reduce((acc, subj) => acc + Number(studentMarks[subj] || 0), 0);
              const percentage = subjects.length > 0 ? (total / subjects.length).toFixed(2) : 0;

              return (
                <tr key={student.id}>
                  <td>{student.name}</td>
                  <td>{student.roll}</td>
                  {subjects.map(subj => (
                    <td key={subj}>{studentMarks[subj] || 0}</td>
                  ))}
                  <td>{total}</td>
                  <td>{percentage}%</td>
                </tr>
              );
            })}
          </tbody>
        </table>
      )}
    </div>
  );
}

export default MarksReport;
